import json, shutil, subprocess, time, os, sys, tempfile
ROOT=os.path.abspath(os.path.join(os.path.dirname(__file__),'..','..'))
TMP=tempfile.mkdtemp(prefix='formdrill-e2e-')
shutil.copytree(ROOT+'/extension',TMP+'/ext')
_m=json.load(open(TMP+'/ext/manifest.json')); _m['host_permissions']=['http://localhost/*']; json.dump(_m,open(TMP+'/ext/manifest.json','w'))
from playwright.sync_api import sync_playwright
srv=subprocess.Popen([sys.executable,'-m','http.server','8765','--directory',ROOT+'/sample'],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL); time.sleep(1)
res=[]
def check(n,c,d=''): res.append(bool(c)); print(('PASS ' if c else 'FAIL ')+n+(' :: '+str(d) if not c and d else ''))
try:
  with sync_playwright() as p:
    ext_path=os.path.normpath(TMP+'/ext')
    ctx=p.chromium.launch_persistent_context(TMP+'/profile',headless=False,args=['--headless=new',f'--disable-extensions-except={ext_path}',f'--load-extension={ext_path}','--no-sandbox'])
    sw=ctx.service_workers[0] if ctx.service_workers else ctx.wait_for_event('serviceworker'); ext=sw.url.split('/')[2]
    reqs=[]; page=ctx.new_page(); page.on('response',lambda r: reqs.append((r.status,r.url)) if r.status>=400 else None); page.goto('http://localhost:8765/forms.html')
    app=ctx.new_page(); app.goto(f'chrome-extension://{ext}/app.html')
    tid=app.evaluate("chrome.tabs.query({url:'http://localhost:8765/*'}).then(t=>t[0].id)")
    app.evaluate("FD.set('profile',{v:1,fields:{fullName:'Test Person',email:'test@example.com',institution:'Example University',country:'India',phone:'555-0100'},facts:[]})")
    pop=ctx.new_page(); pop.add_init_script(f"chrome.tabs.query=async()=>[{{id:{tid},windowId:1}}];")
    pop.goto(f'chrome-extension://{ext}/popup.html'); pop.wait_for_selector('#facts:not([hidden])')
    check('popup shows category + counts',pop.inner_text('#cat')!='' and 'of' in pop.inner_text('#count'),pop.inner_text('#count'))
    check('privacy pill says local only','Local only' in pop.inner_text('#privacy'))
    check('popup undo button disabled before fill',pop.eval_on_selector('#undo','e=>e.disabled'))
    pop.click('#fill'); pop.wait_for_selector('#review:not([hidden])')
    boxes=pop.locator('#review input[type=checkbox]'); n=boxes.count(); on=sum(boxes.nth(i).is_checked() for i in range(n))
    check('review list shown; only high-confidence pre-ticked',n>=4 and on>=1,(n,on))
    check('nothing written before Apply',page.input_value('#s1')=='' and page.input_value('#s2')=='')
    pop.click('text=Apply selected'); pop.wait_for_function("() => document.getElementById('status').textContent.startsWith('Filled')")
    check('apply fills page',page.input_value('#s1')=='Test Person' and page.input_value('#s2')=='test@example.com',pop.inner_text('#status'))
    check('status says FormDrill never submits','never submits' in pop.inner_text('#status'))
    check('popup undo button enabled after fill',not pop.eval_on_selector('#undo','e=>e.disabled'))
    pop.click('text=Undo this fill'); pop.wait_for_function("() => document.getElementById('status').textContent==='Undone.'"); check('undo clears fill',page.input_value('#s1')=='')
    check('popup undo button disabled after undo',pop.eval_on_selector('#undo','e=>e.disabled'))
    # Persistent popup undo test: refilling, reopening popup, restoring, preserving unrelated edits
    pop.click('#fill'); pop.wait_for_selector('#review:not([hidden])')
    pop.click('text=Apply selected'); pop.wait_for_function("() => document.getElementById('status').textContent.startsWith('Filled')")
    pop.reload(); pop.wait_for_selector('#facts:not([hidden])')
    check('popup undo button enabled after popup reload',not pop.eval_on_selector('#undo','e=>e.disabled'))
    page.fill('#i5','https://example.com/my-portfolio')
    pop.click('#undo'); pop.wait_for_function("() => document.getElementById('status').textContent==='Undone.'")
    check('undo restored s1 to empty after reopen',page.input_value('#s1')=='')
    check('undo preserved unrelated user edit',page.input_value('#i5')=='https://example.com/my-portfolio')
    check('popup undo button disabled after undo',pop.eval_on_selector('#undo','e=>e.disabled'))
    page.fill('#i5','')
    pop.click('#save'); pop.wait_for_function("() => /Saved|No filled/.test(document.getElementById('status').textContent)"); check('save with empty form is refused with message','No filled-in fields' in pop.inner_text('#status'),pop.inner_text('#status'))
    page.fill('#s1','Typed By Me'); page.fill('#i7','pw-secret'); pop.fill('#stepname','Step 1: Basics'); pop.click('#save'); pop.wait_for_function("() => document.getElementById('status').textContent.startsWith('Saved')")
    snaps=app.evaluate("FD.get('snapshots',[])"); check('snapshot saved with user step label, no password',len(snaps)==1 and snaps[0]['step']=='Step 1: Basics' and 'pw-secret' not in json.dumps(snaps))
    # snapshot UI: list, restore dialog, delete
    app.evaluate("FD.set('settings',{onboarded:true})"); app.reload(); app.click('role=tab[name="Saved"]'); app.wait_for_selector('text=Review & restore')
    app.evaluate(f"FD.activeTab=async()=>({{id:{tid}}})"); page.fill('#s1','')
    app.click('text=Review & restore'); app.wait_for_selector('dialog[open]'); check('restore dialog warns nothing / lists values','Typed By Me' in app.inner_text('dialog'),app.inner_text('dialog')[:200])
    app.click('text=Restore selected'); app.wait_for_selector('text=Restored'); check('restore through UI refills field',page.input_value('#s1')=='Typed By Me')
    app.on('dialog',lambda d:d.accept()); app.click('text=Delete'); app.wait_for_selector('text=Snapshot deleted'); check('snapshot delete works',app.evaluate("FD.get('snapshots',[])")==[])
    print('HTTP errors:',reqs)
    ctx.close()
finally: srv.terminate()
print(f'{sum(res)}/{len(res)} passed')
